import org.junit.Test;
import org.traccar.model.Position;
import org.traccar.protocol.Gt06ProtocolDecoder;
import org.traccar.protocol.Protocol;
import java.nio.channels.Channel;
import java.net.SocketAddress;
import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import java.util.TimeZone;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class Gt06ProtocolDecoderTest {

    @Test
    public void decodeGpsNoLengthNoTimeZoneTest() {
        Position position = new Position();
        ByteBuf buf = Unpooled.buffer();
        assertFalse(Gt06ProtocolDecoder.decodeGps(position, buf, false, null));
    }

    @Test
    public void decodeGpsWithLengthAndTimeZoneTest() {
        Position position = new Position();
        ByteBuf buf = Unpooled.buffer();
        buf.writeInt(16);
        assertTrue(Gt06ProtocolDecoder.decodeGps(position, buf, true, TimeZone.getDefault()));
    }

    @Test
    public void decodeGpsWithSatellitesSpeedAndTimeZoneTest() {
        Position position = new Position();
        ByteBuf buf = Unpooled.buffer();
        buf.writeInt(16);
        assertTrue(Gt06ProtocolDecoder.decodeGps(position, buf, true, true, true, TimeZone.getDefault()));
    }

    @Test
    public void decodeGpsWithLengthSatellitesNoSpeedAndTimeZoneTest() {
        Position position = new Position();
        ByteBuf buf = Unpooled.buffer();
        buf.writeInt(16);
        assertTrue(Gt06ProtocolDecoder.decodeGps(position, buf, true, true, false, TimeZone.getDefault()));
    }

    @Test
    public void decodeWithNullParamsTest() throws Exception {
        Gt06ProtocolDecoder decoder = new Gt06ProtocolDecoder(new Protocol());
        assertNull(decoder.decode(null, null, null));
    }

    @Test
    public void decodeWithMockedParamsTest() throws Exception {
        Gt06ProtocolDecoder decoder = new Gt06ProtocolDecoder(new Protocol());
        Channel channel = mock(Channel.class);
        SocketAddress address = mock(SocketAddress.class);
        ByteBuf msg = Unpooled.buffer();
        msg.writeInt(16);
        assertNotNull(decoder.decode(channel, address, msg));
    }
}
